/**
 * The book template's chapter-opener / cover botanical artwork, embedded as
 * a base64 data URI for exactly the same reason the fonts in `../fonts/`
 * are: `renderBookPdf` hands Puppeteer a self-contained document via
 * `page.setContent`, which has no base URL, so a relative
 * `/images/...` reference cannot resolve. The same string is also inlined
 * into the staff `srcdoc` preview.
 *
 * Source of truth is nutrition-client's
 * `public/images/books/chapter-cover-bg.png` (1087x1446, lossless). This is
 * a q95 JPEG re-encode of it at the SAME pixel dimensions — no downscaling,
 * so effective print resolution is unchanged (~186 DPI at A5, which is
 * slightly under BOOK_PLAN §14's 200 DPI preference; a higher-resolution
 * source export would be needed to fully clear that floor). Re-encoding
 * dropped 1.11 MB to 154 KB with no visible difference on this soft
 * gradient/botanical art; nutrition-client serves the identical JPEG
 * (`chapter-cover-bg.jpg`) so both renderers rasterize the same bytes.
 *
 * Regenerate with:
 *   sips -s format jpeg -s formatOptions 95 chapter-cover-bg.png --out chapter-cover-bg.jpg
 */
export const CHAPTER_BACKGROUND_DATA_URI =
  "data:image/jpeg;base64,\
";
